                    debtHistory: [62],
                    bondYieldHistory: [3.5]
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    L1: 5, L2: 5, L3: 5, L4: 5, L5: 5, L6: 5,
                    timing: 'T2',
                    contingency: 0,
                    comm_bond: 'structured',
                    comm_voter: 'clear',
                    comm_imf: 'coordinated'
                };
            }
            var self = this;
            setTimeout(function() {
                self._updateBriefing(state);
                self._syncControlsFromDecisions(state);
            }, 120);
        }

        validateDecisions(decisions) {
            var round = window.mySimulation.state.currentPeriod;
            var keys = ['L1','L2','L3','L4','L5','L6'];

            if (round === 1) {
                keys.forEach(function(k) {
                    var el = document.getElementById('input_' + k);
                    if (el) decisions[k] = parseFloat(el.value) || 0;
                });
                if (keys.some(function(k) { return decisions[k] < 0; })) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('negative_warning'), 'warning');
                    return false;
                }
                var sum = keys.reduce(function(a, k) { return a + (decisions[k] || 0); }, 0);
                if (Math.abs(sum - 30) > 0.01) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('sum_warning') + ': ' + sum.toFixed(1) + ' / 30', 'warning');
                    return false;
                }
            }

            if (round === 2) {
                var tEl = document.getElementById('timingSelect');
                if (tEl) decisions.timing = tEl.value;
                var cEl = document.getElementById('contingencyInput');
                if (cEl) decisions.contingency = parseFloat(cEl.value) || 0;
                if (decisions.contingency < 0 || decisions.contingency > 10) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('contingency_warning'), 'warning');
                    return false;
                }
            }

            if (round === 3) {
                var b = document.getElementById('commBondSelect');
                var v = document.getElementById('commVoterSelect');
                var i = document.getElementById('commImfSelect');
                if (b) decisions.comm_bond  = b.value;
                if (v) decisions.comm_voter = v.value;
                if (i) decisions.comm_imf   = i.value;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var round = state.currentPeriod;
            var ds = state.domainState;
            var results = { period: round };
            var keys = ['L1','L2','L3','L4','L5','L6'];

            if (round === 1) {
                var alloc = {};
                keys.forEach(function(k) { alloc[k] = d[k] || 0; });
                var c = this._compose(alloc);
                ds.alloc              = alloc;
                ds.deployed           = c.tot;
                ds.gdpImpact          = c.gdp;
                ds.jobsCreated        = Math.round(c.jobs);
                ds.distributional     = c.dist;
                ds.weightedMultiplier = c.mult;
                ds.speedScore         = c.speed;
                ds.durability         = c.durability;
                ds.permanent          = c.perm;
                // a provisional two-year path at even timing, so the running score already sees delay and incidence
                this._applyPath(ds, this._path(alloc, 'T2', 0, null));
                ds.unemploymentHistory = [8.7]; ds.debtHistory = [62]; ds.bondYieldHistory = [3.5];
                ds.unemployment = 8.7; ds.debtToGDP = 62; ds.bondYield = 3.5;

                results.gdpImpact          = c.gdp;
                results.jobsCreated        = Math.round(c.jobs);
                results.weightedMultiplier = c.mult;
                results.speedScore         = Math.round(c.speed);
                results.distScore          = Math.round(c.dist * 100);
                results.notes              = this._noteFor(results);
            }

            if (round === 2) {
                var tKey = this.TIMING[d.timing] ? d.timing : 'T2';
                var contingency = d.contingency || 0;
                ds.contingency = contingency;
                ds.timing = tKey;
                var pth = this._path(ds.alloc || this._allocFromDecisions(d), tKey, contingency, null);
                this._applyPath(ds, pth);

                results.timing            = this.TIMING[tKey].label;
                results.timingKey         = tKey;
                results.gdpY1             = pth.y1 * ds.weightedMultiplier;
                results.gdpY2             = pth.y2 * ds.weightedMultiplier;
                results.finalUnemployment = ds.unemployment;
                results.finalDebt         = ds.debtToGDP;
                results.finalYield        = ds.bondYield;
                results.notes             = this._noteFor(results);
            }

            if (round === 3) {
                var bondScores  = { vague: 30, structured: 92, technical: 68 };
                var voterScores = { wonky: 32, clear:      90, dismissive: 18 };
                var imfScores   = { separate: 38, coordinated: 95, defensive: 52 };
                var bScore = bondScores[d.comm_bond]   != null ? bondScores[d.comm_bond]   : 50;
                var vScore = voterScores[d.comm_voter] != null ? voterScores[d.comm_voter] : 50;
                var iScore = imfScores[d.comm_imf]     != null ? imfScores[d.comm_imf]     : 50;

                ds.credibilityBond  = bScore;
                ds.credibilityVoter = vScore;
                ds.credibilityIMF   = iScore;
                ds.msg = { b: d.comm_bond || '', v: d.comm_voter || '', i: d.comm_imf || '' };

                // the messages go out with the package: the bond answer moves the yield (and the interest bill),
                // the IMF answer says whether the bank is expected to hold its floor or lean against the stimulus
                this._applyPath(ds, this._path(ds.alloc || this._allocFromDecisions(d), ds.timing || 'T2', ds.contingency || 0, ds.msg));

                results.credibilityBond  = bScore;
                results.credibilityVoter = vScore;
                results.credibilityIMF   = iScore;
                results.avgCredibility   = Math.round((bScore + vScore + iScore) / 3);
                results.finalUnemployment = ds.unemployment;
                results.finalDebt         = ds.debtToGDP;
                results.finalYield        = ds.bondYield;
                results.notes            = this._noteFor(results);
            }

            // platform score: the same composite as the debrief (five criteria, clamped 0-100) on the state so far
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, {
                overallScore: this._runningScore(ds)
            });
            results.overallScore = state.domainState.performance.overallScore;
            results.score = results.overallScore;

            var self = this;
            var nextPeriod = round + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod, domainState: state.domainState });
            }, 500);

            return results;
        }

        // history note of one round, built from its results with translated words so the table can redraw it in the current language
        _noteFor(r) {
            var t = this._t.bind(this);
            r = r || {};
            if (r.period === 1) {
                return t('round1_done')
                    + ' μ=' + (r.weightedMultiplier || 0).toFixed(2)
                    + ', ' + t('note_gdp') + '+CO$' + (r.gdpImpact || 0).toFixed(1) + t('unit_bn')
                    + ', ' + Math.round(r.jobsCreated || 0).toLocaleString() + ' ' + t('jobs_word');
            }
            if (r.period === 2) {
                var name = r.timingKey ? t('timing_name_' + r.timingKey) : (r.timing || '');
                return t('round2_done')
                    + ' ' + name
                    + ', ' + t('note_unemp') + '→' + (r.finalUnemployment || 0).toFixed(1) + '%'
                    + ', ' + t('note_debt') + '→' + (r.finalDebt || 0).toFixed(1) + '%'
                    + ', ' + t('note_yield') + '→' + (r.finalYield || 0).toFixed(2) + '%';
            }
            if (r.period === 3) {
                return t('round3_done')
                    + ' ' + t('note_bond') + '=' + r.credibilityBond + ', ' + t('note_voter') + '=' + r.credibilityVoter + ', ' + t('note_imf') + '=' + r.credibilityIMF
                    + ', ' + t('avg_word') + '=' + r.avgCredibility + '/100';
            }
            return r.notes || '';
        }

        _allocFromDecisions(d) {
            var a = {};
            ['L1','L2','L3','L4','L5','L6'].forEach(function(k) { a[k] = (d && d[k]) || 0; });
            return a;
        }

        // average multiplier of x billion in one lever: linear slide from the top of the staff range to its bottom
        // over the first CAP billion, then a further fade (absorption) up to CO$30bn
        _avgMult(k, x) {
            var L = this.LEVERS[k], M = this.MODEL, C = M.cap, r = L.hi - L.lo;
            if (x <= 0) return L.hi;
            if (x <= C) return L.hi - r * x / (2 * C);
            var e = x - C, tail = L.lo * e - L.lo * M.fade * e * e / (2 * (30 - C));
            return (C * (L.hi + L.lo) / 2 + tail) / x;
        }

        _compose(a) {
            var self = this, tot = 0, gdp = 0, jobs = 0, dist = 0, lag = 0, perm = 0, m = {};
            ['L1','L2','L3','L4','L5','L6'].forEach(function(k) {
                var x = a[k] || 0, L = self.LEVERS[k];
                m[k] = self._avgMult(k, x);
                tot += x; gdp += x * m[k]; jobs += x * L.jobsPerBn; dist += x * L.dist; lag += x * L.lagQ * 3; perm += x * L.perm;
            });
            var avgLag = tot > 0 ? lag / tot : 12;
            return {
                tot: tot, gdp: gdp, jobs: jobs, m: m, perm: perm,
                mult: tot > 0 ? gdp / tot : 0,
                dist: tot > 0 ? dist / tot : 0,
                speed: Math.max(0, Math.min(100, 100 - (avgLag / 18) * 100)),
                // what outlasts the recession: assets (infrastructure) and skills (retraining), with diminishing returns
                durability: 0.7 * Math.sqrt((a.L4 || 0) / 30) + 0.3 * Math.sqrt((a.L6 || 0) / 30)
            };
        }

        // the two-year path, quarter by quarter. Each lever's spending reaches the economy after its delay;
        // output that lands later meets a turning cycle; unemployment above 7.8% scars (hysteresis), less so
        // with retraining; the yield feeds the interest bill
        _path(a, timing, reserve, msg) {
            var self = this, M = this.MODEL, c = this._compose(a), t = this.TIMING[timing] || this.TIMING.T2, res = reserve || 0, q, k;
            msg = msg || {};
            var crowd = msg.i === 'separate' ? 0.82 : (msg.i === 'defensive' ? 0.9 : 1);
            var yMsg = msg.b === 'vague' ? 0.36 : (msg.b === 'technical' ? -0.10 : (msg.b === 'structured' ? -0.38 : 0));
            // the reserve is held back from Year 1 and released in Year 2: the package stays CO$30bn
            var y1 = t.y1 * (1 - res / 30), y2 = t.y2 + t.y1 * res / 30;
            var spend = [0], land = [];
            for (q = 1; q <= 8; q++) spend.push(q <= 4 ? y1 / 4 : y2 / 4);
            for (q = 0; q < 16; q++) land.push(0);
            ['L1','L2','L3','L4','L5','L6'].forEach(function(k2) {
                var x = a[k2] || 0;
                if (!x || !c.tot) return;
                var dl = self.LEVERS[k2].lagQ, f = Math.floor(dl), w = dl - f;
                for (var j = 1; j <= 8; j++) {
                    var o = spend[j] * x / c.tot * c.m[k2];
                    land[j + f] += o * (1 - w);
                    land[j + f + 1] += o * w;
                }
            });
            var u = 8.7, ub = 8.7, debt = 62, y = 3.5 + t.yieldShock * 0.4, inWin = 0, late = 0, red = 0;
            var U = [8.7], D = [62], Y = [Number((y + yMsg).toFixed(4))];
            var retrain = Math.min(0.6, (a.L6 || 0) / 10);
            for (q = 1; q <= 8; q++) {
                var o2 = land[q] * M.cyc[q] * (q > 4 ? crowd : 1);
                inWin += o2;
                u = Math.max(4.5, u - M.okun * (o2 + M.auto) + M.scar * Math.max(0, u - M.scarAt) * (1 - retrain));
                ub = Math.max(4.5, ub - M.okun * M.auto + M.scar * Math.max(0, ub - M.scarAt));
                red += ub - u;
                U.push(u);
                y = Math.max(2.4, y + ((q <= 4 && timing === 'T1') ? 0.18 : ((q <= 4 && timing === 'T3') ? -0.04 : -0.03)) + (q === 1 ? yMsg : 0));
                Y.push(y);
                debt = debt + spend[q] * 0.45 - (q > 4 ? (o2 + M.auto) * 0.08 : 0) + (y - 3.5) * 0.62 / 4;
                D.push(debt);
            }
            for (q = 9; q < 16; q++) late += land[q] * M.cycLate * crowd;
            return { U: U, D: D, Y: Y, u: u, debt: debt, y: y, baseU: ub, meanRelief: red / 8,
                     inWindow: inWin, lateOutput: late, effMult: (inWin + late) / 30, y1: y1, y2: y2,
                     debtOutlook: debt + 0.6 * c.perm };
        }

        _applyPath(ds, p) {
            ds.unemploymentHistory = p.U;
            ds.debtHistory         = p.D;
            ds.bondYieldHistory    = p.Y;
            ds.unemployment        = p.u;
            ds.debtToGDP           = p.debt;
            ds.bondYield           = p.y;
            ds.meanRelief          = p.meanRelief;
            ds.effMult             = p.effMult;
            ds.inWindowShare       = p.inWindow + p.lateOutput > 0 ? p.inWindow / (p.inWindow + p.lateOutput) : 0;
            ds.debtOutlook         = p.debtOutlook;
            ds.baselineUnemployment = p.baseU;
        }

        // the five criteria of the President's policy unit, each 0-100 (one function feeds the score, the grade,
        // the gradebook and the debrief)
        _criteria(ds) {
            var lin = function(v, lo, hi) { return Math.max(0, Math.min(100, 100 * (v - lo) / (hi - lo))); };
            var avgCred = ((ds.credibilityBond || 0) + (ds.credibilityVoter || 0) + (ds.credibilityIMF || 0)) / 3;
            return {
                relief: lin(ds.meanRelief || 0, 0.2, 0.9),
                output: lin(ds.effMult || 0, 0.75, 1.15),
                reach:  0.5 * lin(ds.durability || 0, 0, 0.6) + 0.5 * lin(ds.distributional || 0, 0, 0.8),
                debt:   100 - 0.5 * lin(ds.debtOutlook || ds.debtToGDP || 62, 72.5, 77) - 0.5 * lin(ds.bondYield || 3.5, 3.4, 4.4),
                cred:   lin(avgCred, 20, 92),
                avgCred: avgCred
            };
        }

        _compositeRaw(ds) {
            var c = this._criteria(ds);
            var s = 0.20 * c.relief + 0.20 * c.output + 0.20 * c.reach + 0.15 * c.debt + 0.25 * c.cred;
            return Math.max(0, Math.min(100, s));
        }

        _runningScore(ds) {
            return Math.round(this._compositeRaw(ds));
        }

        // one function: band from the rounded score that is shown and graded
        _tier(score) {
            if (score >= 78) return 'cabinet_grade';
            if (score >= 62) return 'strong';
            if (score >= 45) return 'adequate';
            return 'beginner';
        }

        _updateBriefing(state) {
            var round = state.currentPeriod || 1;
            var over = round > 3;
            var briefEl = document.getElementById('briefingText');
            var keyMap = { 1: 'briefing_round1', 2: 'briefing_round2', 3: 'briefing_round3', 4: 'briefing_done' };
            if (briefEl && window.mySimulation && window.mySimulation.t) {
                briefEl.innerHTML = window.mySimulation.t(keyMap[round] || 'briefing_done');
            }

            var p1 = document.getElementById('round1Panel');
            var p2 = document.getElementById('round2Panel');
            var p3 = document.getElementById('round3Panel');
            if (p1) p1.style.display = round === 1 ? 'block' : 'none';
            if (p2) p2.style.display = round === 2 ? 'block' : 'none';
            if (p3) p3.style.display = round === 3 ? 'block' : 'none';

            var actions = document.querySelector('.fiscal-sim-actions');
            if (actions) actions.style.display = over ? 'none' : 'flex';
            var done = document.getElementById('completionPanel');
            if (done) {
                done.style.display = over ? 'block' : 'none';
                if (over && !done.innerHTML) {
                    done.innerHTML = (window.mySimulation && window.mySimulation.lastCompletionHTML) ||
                        ('<div class="fiscal-sim-debrief"><h3>' + this._t('debrief_heading') + '</h3></div>');
                }
            }

            this._updateRemaining();
        }

        _t(key) {
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                var v = window.mySimulation.t(key);
                if (v) return v;
            }
            return key;
        }

        _syncControlsFromDecisions(state) {
            var dec = (state && state.decisions) || {};
            ['L1','L2','L3','L4','L5','L6'].forEach(function(k) {
                var el = document.getElementById('input_' + k);
                if (el && typeof dec[k] === 'number') el.value = String(dec[k]);
            });
            var pairs = [['timingSelect','timing'], ['commBondSelect','comm_bond'],
                         ['commVoterSelect','comm_voter'], ['commImfSelect','comm_imf']];
            pairs.forEach(function(p) {
                var el = document.getElementById(p[0]);
                if (el && dec[p[1]]) el.value = dec[p[1]];
            });
            var cEl = document.getElementById('contingencyInput');
            if (cEl && typeof dec.contingency === 'number') cEl.value = String(dec.contingency);
        }

        _updateRemaining() {
            var sum = 0;
            ['L1','L2','L3','L4','L5','L6'].forEach(function(k) {
                var el = document.getElementById('input_' + k);
                if (el) sum += parseFloat(el.value) || 0;
            });
            var rem = document.getElementById('remainingDisplay');
            if (rem) {
                rem.innerHTML = sum.toFixed(1) + ' / 30';
                rem.style.color = Math.abs(sum - 30) < 0.01 ? '#2d6a4f' : '#c1272d';
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay',          'currentPeriod');
            uiManager.bind('maxPeriods',          'maxPeriods');
            var unit = this._t.bind(this);
            uiManager.bind('packageDisplay',      'domainState.deployed',           function(v) { return 'CO$' + (v || 0).toFixed(1) + unit('unit_bn'); });
            uiManager.bind('gdpImpactDisplay',    'domainState.gdpImpact',          function(v) { return 'CO$' + (v || 0).toFixed(1) + unit('unit_bn'); });
            uiManager.bind('jobsDisplay',         'domainState.jobsCreated',        function(v) { return Math.round(v || 0).toLocaleString(); });
            uiManager.bind('unemploymentDisplay', 'domainState.unemployment',       function(v) { return (v || 0).toFixed(1) + '%'; });
            uiManager.bind('debtDisplay',         'domainState.debtToGDP',          function(v) { return (v || 0).toFixed(1) + '%'; });
            uiManager.bind('yieldDisplay',        'domainState.bondYield',          function(v) { return (v || 0).toFixed(2) + '%'; });
            uiManager.bind('multiplierDisplay',   'domainState.weightedMultiplier', function(v) { return (v || 0).toFixed(2) + 'x'; });
            uiManager.bind('credibilityDisplay',  'domainState.credibilityBond',    function(v) { return Math.round(v || 0) + '/100'; });

            var self = this;
            setTimeout(function() {
                ['L1','L2','L3','L4','L5','L6'].forEach(function(k) {
                    var el = document.getElementById('input_' + k);
                    if (el) el.addEventListener('input', function() { self._updateRemaining(); });
                });
                self._updateBriefing(window.mySimulation.state);
            }, 220);
        }

        _quarterLabels() {
            var out = [];
            for (var q = 0; q <= 8; q++) out.push(this._t('chart_quarter') + q);
            return out;
        }

        getChartConfig() {
            return {
                pathChart: {
                    type: 'line',
                    data: {
                        labels: this._quarterLabels(),
                        datasets: [
                            {
                                label: this._t('chart_unemp'),
                                data: [],
                                borderColor: '#c1272d',
                                backgroundColor: 'rgba(193,39,45,0.08)',
                                borderWidth: 2.5,
                                tension: 0.25,
                                yAxisID: 'y'
                            },
                            {
                                label: this._t('chart_yield'),
                                data: [],
                                borderColor: '#d4a017',
                                backgroundColor: 'rgba(212,160,23,0.08)',
                                borderWidth: 2.5,
                                tension: 0.25,
                                yAxisID: 'y'
                            },
                            {
                                label: this._t('chart_debt'),
                                data: [],
                                borderColor: '#1a2744',
                                backgroundColor: 'rgba(26,39,68,0.08)',
                                borderWidth: 2.5,
                                tension: 0.25,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        interaction: { mode: 'index', intersect: false },
                        plugins: {
                            title: { display: true, text: this._t('chart_title') },
                            legend: { position: 'bottom', labels: { boxWidth: 14, font: { size: 11 } } }
                        },
                        scales: {
                            y:  { type: 'linear', position: 'left',  title: { display: true, text: this._t('chart_axis_left') } },
                            y1: { type: 'linear', position: 'right', title: { display: true, text: this._t('chart_debt') }, grid: { drawOnChartArea: false } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            // chart points at the precision the dashboard cards show; copies, so the state keeps its exact path
            var at = function(arr, d) {
                return (arr || []).map(function(v) { return typeof v === 'number' ? Number(v.toFixed(d)) : v; });
            };
            return {
                pathChart: {
                    labels: this._quarterLabels(),
                    datasets: [
                        { data: at(ds.unemploymentHistory, 1), label: this._t('chart_unemp') },
                        { data: at(ds.bondYieldHistory, 2),    label: this._t('chart_yield') },
                        { data: at(ds.debtHistory, 1),         label: this._t('chart_debt') }
                    ]
                }
            };
        }

        getHint(state, results) {
            // the EQIL guard hands this the round that was just scored, so each hint follows its own decision
            var d = state.decisions || {};
            var round = state.currentPeriod;
            var t = this._t.bind(this);
            if (round === 1) {
                if (((d.L1 || 0) + (d.L2 || 0)) > 20) return t('hint_taxheavy');
                if ((d.L4 || 0) >= 22)                 return t('hint_infraonly');
                if (((d.L3 || 0) + (d.L6 || 0)) < 5)   return t('hint_no_progressive');
            }
            if (round === 2) {
                if (d.timing === 'T1') return t('hint_frontload_comm');
                if (d.timing === 'T3') return t('hint_backload_comm');
            }
            if (round === 3 && results) {
                if (results.avgCredibility < 55) return t('hint_lowcred');
            }
            return null;
        }

        getHistoryTableConfig() {
            var self = this;
            // the outcome column redraws the note from the round results, so it follows the current language
            return [
                { key: 'period',        label: 'Round',   i18nKey: 'col_round' },
                { key: 'results',       label: 'Outcome', i18nKey: 'col_outcome', formatter: function(r) { return (r && typeof r === 'object') ? self._noteFor(r) : r; } }
            ];
        }

        getPresets() { return null; }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var ds = window.mySimulation.state.domainState || {};
            var self = this, t = this._t.bind(this);
            var crit = this._criteria(ds);
            var overall = this._runningScore(ds);
            var perf = this._tier(overall);
            var perfKey = 'perf_' + perf;
            var a = ds.alloc || {}, msg = ds.msg || {};
            var fmt = function(key, vars) {
                return String(t(key)).replace(/\{(\w+)\}/g, function(all, n) { return vars && vars[n] !== undefined ? vars[n] : all; });
            };
            var dec = function(v, n) { var x = Number(v || 0).toFixed(n); return self._lang() === 'es' ? x.replace('.', ',') : x; };

            // insights built from this run's own decisions; the mistakes of the teaching note are named where made
            var notes = [];
            if ((a.L4 || 0) >= 20) notes.push({ w: 3, k: 'ins_m_infra', v: { x: dec(a.L4, 1), p: Math.round(100 * (ds.inWindowShare || 0)) } });
            if ((a.L1 || 0) >= 8 || ((a.L1 || 0) + (a.L2 || 0)) >= 15) notes.push({ w: 3, k: 'ins_m_tax', v: { x: dec((a.L1 || 0) + (a.L2 || 0), 1) } });
            if (ds.timing === 'T3') notes.push({ w: 3, k: 'ins_m_backload', v: { u: dec((ds.unemploymentHistory || [])[4], 2) } });
            if (msg.b === 'technical' || msg.v === 'wonky') notes.push({ w: 2, k: 'ins_m_wonk', v: {} });
            if (msg.i === 'separate') notes.push({ w: 2, k: 'ins_m_separate', v: {} });
            if (msg.b === 'vague') notes.push({ w: 2, k: 'ins_vague', v: { y: dec(ds.bondYield, 2) } });
            if (msg.v === 'dismissive') notes.push({ w: 2, k: 'ins_dismissive', v: {} });
            if (ds.timing === 'T1' && (ds.bondYield || 0) > 4) notes.push({ w: 2, k: 'ins_frontload', v: { y: dec(ds.bondYield, 2) } });
            if ((ds.permanent || 0) >= 6) notes.push({ w: 1, k: 'ins_permanent', v: { x: dec(ds.permanent, 1) } });
            if ((ds.contingency || 0) > 0) notes.push({ w: 1, k: 'ins_reserve', v: { x: dec(ds.contingency, 1) } });
            if (!(a.L6 > 0) && (ds.unemployment || 0) > 7.5) notes.push({ w: 1, k: 'ins_scar', v: { u: dec(ds.unemployment, 2) } });
            notes.sort(function(x, y) { return y.w - x.w; });
            var insights = notes.slice(0, 4).map(function(n) { return fmt(n.k, n.v); });
            // what went right, from the same run
            var good = [];
            if (crit.relief >= 60) good.push(fmt('ins_g_relief', { r: dec(ds.meanRelief, 2) }));
            if (crit.reach >= 60) good.push(t('ins_g_reach'));
            if (crit.cred >= 85) good.push(t('ins_g_cred'));
            if (crit.output >= 70) good.push(fmt('ins_g_output', { m: dec(ds.effMult, 2) }));
            while (insights.length < 3 && good.length) insights.push(good.shift());
            if (insights.length < 3) insights.push(fmt('ins_path', { u: dec(ds.unemployment, 2), d: dec(ds.debtToGDP, 1) }));

            // turning point: the criterion that cost the most, and the decision behind it
            var names = { relief: 1, output: 1, reach: 1, debt: 2, cred: 3 };
            var worst = 'relief';
            ['output', 'reach', 'debt', 'cred'].forEach(function(k) { if (crit[k] < crit[worst]) worst = k; });
            var turning = fmt('turn_' + worst, { s: Math.round(crit[worst]), r: names[worst] });

            return {
                composite:         overall,
                overallScore:      overall,
                totalScore:        overall,
                score:             overall,
                avgMultiplier:     Number((ds.weightedMultiplier || 0).toFixed(2)),
                jobs:              Math.round(ds.jobsCreated || 0),
                finalUnemployment: Number((ds.unemployment || 8.7).toFixed(1)),
                finalDebt:         Number((ds.debtToGDP || 62).toFixed(1)),
                finalYield:        Number((ds.bondYield || 3.5).toFixed(2)),
                avgCredibility:    Math.round(crit.avgCred),
                criteria: {
                    relief: Math.round(crit.relief), output: Math.round(crit.output), reach: Math.round(crit.reach),
                    debt: Math.round(crit.debt), cred: Math.round(crit.cred)
                },
                performance:       perf,
                performanceTier:   perf,
                performanceKey:    perfKey,
                performanceLabel:  this._t(perfKey),
                turningPoint:      turning,
                insights:          insights,
                questions:         [t('q_1'), t('q_2'), t('q_3')]
            };
        }

        _lang() {
            var l = '';
            try { if (window.vcI18n && window.vcI18n._lang) l = window.vcI18n._lang; } catch (e) {}
            if (!l) l = document.documentElement.lang || 'en';
            return String(l).slice(0, 2).toLowerCase();
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var self = this;
            var t = function(k) { return self._t(k); };
            var esc = function(v) {
                return String(v === undefined || v === null ? '' : v)
                    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            };
            var es = this._lang() === 'es';
            var num = function(v, n) { var x = Number(v || 0).toFixed(n); return es ? x.replace('.', ',') : x; };
            var rows = [
                [t('debrief_multiplier'), num(s.avgMultiplier, 2) + 'x'],
                [t('debrief_jobs'), Math.round(s.jobs || 0).toLocaleString(es ? 'es' : 'en')],
                [t('debrief_unemp'), num(s.finalUnemployment, 1) + '%'],
                [t('debrief_debt'), num(s.finalDebt, 1) + '%'],
                [t('debrief_yield'), num(s.finalYield, 2) + '%'],
                [t('debrief_cred'), esc(s.avgCredibility) + '/100']
            ].map(function(r) {
                return '<li><span class="fiscal-sim-debrief-k">' + esc(r[0]) + '</span>' +
                       '<span class="fiscal-sim-debrief-v">' + esc(r[1]) + '</span></li>';
            }).join('');
            var cr = s.criteria || {};
            var crit = ['relief', 'output', 'reach', 'debt', 'cred'].map(function(k) {
                return '<li><span class="fiscal-sim-debrief-k">' + esc(t('crit_' + k)) + '</span>' +
                       '<span class="fiscal-sim-debrief-v">' + esc(cr[k] != null ? cr[k] : 0) + '/100</span></li>';
            }).join('');
            var ins = (s.insights || []).map(function(x) { return '<li>' + esc(x) + '</li>'; }).join('');
            var qs = (s.questions || []).map(function(x) { return '<li>' + esc(x) + '</li>'; }).join('');
            return '<div class="fiscal-sim-debrief">' +
                     '<h3>' + esc(t('debrief_heading')) + '</h3>' +
                     '<p class="fiscal-sim-debrief-headline">' + esc(t('debrief_score')) + ' <strong>' +
                       esc(s.overallScore || 0) + '/100</strong> &middot; ' + esc(s.performanceLabel || '') + '</p>' +
                     '<ul class="fiscal-sim-debrief-list">' + rows + '</ul>' +
                     '<h4>' + esc(t('debrief_criteria')) + '</h4>' +
                     '<ul class="fiscal-sim-debrief-list">' + crit + '</ul>' +
                     '<h4>' + esc(t('debrief_turning')) + '</h4><p>' + esc(s.turningPoint || '') + '</p>' +
                     '<h4>' + esc(t('debrief_insights')) + '</h4>' +
                     '<ul class="fiscal-sim-debrief-insights">' + ins + '</ul>' +
                     '<h4>' + esc(t('debrief_questions')) + '</h4>' +
                     '<ol class="fiscal-sim-debrief-questions">' + qs + '</ol>' +
                   '</div>';
        }

